import{_ as l,a0 as o,w as p,s as d,ao as r,I as a,x as t,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"當 Rust 遇上 Fedora | LCTT x X-CMD","titleTemplate":false,"description":"當 Rust 遇上 Fedora | LCTT (201610) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"當 Rust 遇上 Fedora | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"當 Rust 遇上 Fedora | LCTT (201610) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201610/20160921 Rust meets Fedora","title":"當 Rust 遇上 Fedora","tag":"201610","desc":""},"relativePath":"201610/20160921 Rust meets Fedora.md","filePath":"[post].md"}'),u={name:"201610/20160921 Rust meets Fedora.md"};function g(h,s,f,m,k,b){const e=o("Link");return p(),d("div",null,[s[19]||(s[19]=r('<h1 id="當-rust-遇上-fedora" tabindex="-1">當 Rust 遇上 Fedora <a class="header-anchor" href="#當-rust-遇上-fedora" aria-label="Permalink to “當 Rust 遇上 Fedora”">​</a></h1><p><img src="https://i2.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/09/rust.jpg?fit=945%2C400&amp;ssl=1" alt="rust"></p><h3 id="rust-是什麼" tabindex="-1">Rust 是什麼？ <a class="header-anchor" href="#rust-是什麼" aria-label="Permalink to “Rust 是什麼？”">​</a></h3>',3)),a("p",null,[s[1]||(s[1]=t("Rust 是一種系統編程語言，它運行速度驚人，並且可以避免幾乎所有的崩潰、",-1)),i(e,{href:"https://wikipedia.org/wiki/Segmentation_fault"},{default:n(()=>[...s[0]||(s[0]=[t("內存區塊錯誤",-1)])]),_:1}),s[2]||(s[2]=t(" 以及數據競爭。你也許會質疑為什麼我們還需要又一種這樣的語言，因為已經有很多同類的語言了。這篇文章將會告訴你為什麼。",-1))]),s[20]||(s[20]=a("h3",{id:"安全性-vs-控制權",tabindex:"-1"},[t("安全性 vs. 控制權 "),a("a",{class:"header-anchor",href:"#安全性-vs-控制權","aria-label":"Permalink to “安全性 vs. 控制權”"},"​")],-1)),s[21]||(s[21]=a("p",null,[a("img",{src:"https://i0.wp.com/cdn.fedoramagazine.org/wp-content/uploads/2016/09/Screenshot-from-2016-09-12-08-29-02.png?&ssl=1",alt:"為什麼選擇 Rust？"})],-1)),a("p",null,[s[4]||(s[4]=t("你也許見過上面的圖譜。一邊是 C/C++，對運行的硬件擁有更多的控制權，因此它可以讓開發者通過對所生成的機器代碼進行更精細的控制來優化性能。然而這不是很安全，這很容易造成內存區塊錯誤以及像 ",-1)),i(e,{href:"https://fedoramagazine.org/update-on-cve-2014-0160-aka-heartbleed/"},{default:n(()=>[...s[3]||(s[3]=[t("心血漏洞",-1)])]),_:1}),s[5]||(s[5]=t(" 這樣的安全漏洞。",-1))]),s[22]||(s[22]=r(`<p>另一邊是像 Python、Ruby 和 JavaScript 這種沒有給予開發者多少控制權但是可以創建出更安全的代碼的語言。雖然這些代碼可以生成相當安全並且可控的異常，但是它們不會造成內存區塊錯誤。</p><p>在圖譜中間的區域是 Java 和一些其它混合了這些特性的語言。它們提供對運行的硬件部分控制權，並且嘗試儘量減少漏洞的出現。</p><p>Rust 有點不太一樣，它並沒有出現在這個圖譜上。它同時提供給開發者安全性和控制權。</p><h3 id="rust-的特性" tabindex="-1">Rust 的特性 <a class="header-anchor" href="#rust-的特性" aria-label="Permalink to “Rust 的特性”">​</a></h3><p>Rust 是一種像 C/C++ 一樣的系統編程語言，除此之外它還給予開發者對內存分配細粒度的控制。它不需要垃圾回收器。它的運行環境（runtime）很小，運行速度接近於在裸機上的運行。它為開發者提供了代碼性能更大的保證。此外，任何瞭解 C/C++ 的人都能讀懂以及編寫 Rust 的代碼。</p><p>Rust 的運行速度非常快，因為它是一種編譯語言。它使用 LLVM 作為編譯器的後端，並且還可以利用一大堆優化。在許多領域，它的性能都要高於 C/C++。它像 JavaScript、Ruby 和 Python 一樣，與生俱來就是安全的，這意味着它們不會造成內存區塊錯誤、野指針（dangling pointers）或者空指針（null pointers）。</p><p>另外一個很重要的特性就是消除數據競爭。如今，大多數計算機都具有多個核心，許多線程併發運行。然而，開發者很難編寫好的並行代碼，因此這個特性除去了他們的後顧之憂。Rust 使用兩個關鍵概念來消除數據競爭：</p><ul><li>所有權（Ownership）。每一個變量都被移動到一個新的位置，並防止通過先前的位置來引用它。每一個數據塊只有一個所有者。</li><li>借用（Borrowing）。被擁有的值可以借用，以允許在一段時間內使用。</li></ul><h3 id="在-fedora-24-和-25-上使用-rust" tabindex="-1">在 Fedora 24 和 25 上使用 Rust <a class="header-anchor" href="#在-fedora-24-和-25-上使用-rust" aria-label="Permalink to “在 Fedora 24 和 25 上使用 Rust”">​</a></h3><p>若要開始使用，只需安裝軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf install rust</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>fn main() {</span></span>
<span class="line"><span>    println!(&quot;Hello, Rust is running on Fedora 25 Alpha!&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rustc helloworld.rs</span></span>
<span class="line"><span>./helloworld</span></span></code></pre></div><p>在 Fedora 上執行以下命令來安裝最新的測試版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo dnf --enablerepo=updates-testing --refresh --best install rust</span></span></code></pre></div><hr>`,16)),a("p",null,[s[7]||(s[7]=t("via: ",-1)),i(e,{href:"https://fedoramagazine.org/rust-meets-fedora/"},{default:n(()=>[...s[6]||(s[6]=[t("https://fedoramagazine.org/rust-meets-fedora/",-1)])]),_:1})]),a("p",null,[s[11]||(s[11]=t("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/sumantrom/"},{default:n(()=>[...s[8]||(s[8]=[t("Sumantro Mukherjee",-1)])]),_:1}),s[12]||(s[12]=t(" 譯者：",-1)),i(e,{href:"https://github.com/OneNewLife"},{default:n(()=>[...s[9]||(s[9]=[t("OneNewLife",-1)])]),_:1}),s[13]||(s[13]=t(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[10]||(s[10]=[t("wxy",-1)])]),_:1})]),a("p",null,[s[16]||(s[16]=t("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[14]||(s[14]=[t("LCTT",-1)])]),_:1}),s[17]||(s[17]=t(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[15]||(s[15]=[t("Linux中國",-1)])]),_:1}),s[18]||(s[18]=t(" 榮譽推出",-1))])])}const x=l(u,[["render",g]]);export{T as __pageData,x as default};
